const std = @import("std");
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    defer _ = gpa.deinit();
    const list = try allocator.alloc(u8, 16);
    defer allocator.free(list);
    std.debug.print("len={d}\n", .{list.len});
}
